\begin{proposition}
\label{prop:tbq}
The number of elements in $S_{n}$ of cycle type $(b^{q})$ $(n = bq)$ is given by

\begin{align}
\vt{T(b, q)} = \f{n!}{b^{q}q!}.
\end{align}
\end{proposition}

