\begin{lemma}
\label{lem:gamma-at}
Let $\Gamma$ be the gamma function. If $a > 0$ and $t \ge 1$, then
\begin{align}
\Gamma(a+t+1) \le (a+t)^{t}\,\Gamma(a+1).
\end{align}
Equality holds if and only if $t=1$.
\end{lemma}

