\end{align}
and
\begin{align}
\f{R(3, q+2)}{R(3, q)} &= \f{(2(q+2))!}{2^{q+2}3^{q+2}(q+2)!\left(\f{q+3}{2}\right)!\left(\f{q+1}{2}\right)!}\left(\f{1}{3}\right)^{\f{q+1}{2}}
