&= \f{4(2q+1)(2q+3)}{27(q+1)(q+3)} = \f{16}{27}\cdot\f{q+\f{1}{2}}{q+1}\cdot\f{q+\f{3}{2}}{q+3} < 1 \q (q \ge 3).
\end{align}
